using System;using System.Collections.Generic;using System.Diagnostics;using Beast.Claw.Attributes;using Beast.Claw.Common;using Beast.Claw.Math;using Beast.Claw.Reflection;using Unity.Mathematics;namespace Beast.Claw.Debug{    [InitializedWithDomain]    public static class BDebug    {        public static IReadOnlyDictionary<Type, DebugTrackStorage> TrackStorage => TRACK_STORAGE;                private static readonly Dictionary<Type, DebugTrackStorage> TRACK_STORAGE;        static BDebug()        {            try            {                TRACK_STORAGE = new Dictionary<Type, DebugTrackStorage>();            }            catch (Exception e)            {                _logException(e);            }        }        public static void ClearTrackStorage()        {            TRACK_STORAGE.Clear();        }                [Conditional("UNITY_EDITOR")]        public static void Track<T>(T owner, string id, int value)        {            _getOrCreateTrackStorage(owner).Write(id, value);        }                [Conditional("UNITY_EDITOR")]        public static void Track<T>(T owner, string id, float value)        {            _getOrCreateTrackStorage(owner).Write(id, value);        }        [Conditional("UNITY_EDITOR")]        public static void Track<T>(T owner, string id, float2 value)        {            _getOrCreateTrackStorage(owner).Write(id, value);        }                [Conditional("UNITY_EDITOR")]        public static void Track<T>(T owner, string id, float3 value)        {            _getOrCreateTrackStorage(owner).Write(id, value);        }                [Conditional("UNITY_EDITOR")]        public static void Track<T>(T owner, string id, float4 value)        {            _getOrCreateTrackStorage(owner).Write(id, value);        }                [Conditional("UNITY_EDITOR")]        public static void Track<T>(T owner, string id, string value)        {            _getOrCreateTrackStorage(owner).Write(id, value);        }                [Conditional("UNITY_EDITOR")]        public static void Track<T>(T owner, string id, bool value)        {            _getOrCreateTrackStorage(owner).Write(id, value);        }                public static void LogInfo<T>(T owner, string message, object context = null)        {            _logInfo(TypeStorage<T>.FULL_NAME + ": " + message, context);        }                public static void LogError<T>(T owner, string message, object context = null)        {            _logError(TypeStorage<T>.FULL_NAME + ": " + message, context);        }        public static void LogWarning<T>(T owner, string message, object context = null)        {            _logWarning(TypeStorage<T>.FULL_NAME + ": " + message, context);        }        public static void LogException(Exception e)        {            _logException(e);        }                public static void StaticLogError(string message, object context = null)        {            _logError(message, context);        }        public static void StaticLogInfo(string message, object context = null)        {            _logInfo(message, context);        }                public static void StaticLogWarning(string message, object context = null)        {            _logWarning(message, context);        }        /// <summary>        /// Tells that method should not be used in _tick() / _render() etc.         /// </summary>        [Conditional("DEVELOPMENT")]        public static void NotifyPerformanceCriticalContext()        {            Int32Mask a;                        a.value = 1;            // Never executed.            if (a.value == 0)            {                UnityEngine.Debug.Log(string.Empty);            }        }        private static void _logInfo(string message, object context)        {            if (context is UnityEngine.Object unityObject)            {                UnityEngine.Debug.Log(message, unityObject);                return;            }                        UnityEngine.Debug.Log(message);        }        private static void _logWarning(string message, object context)        {            if (context is UnityEngine.Object unityObject)            {                UnityEngine.Debug.LogWarning(message, unityObject);                return;            }                        UnityEngine.Debug.LogWarning(message);        }                private static void _logError(string message, object context)        {            if (context is UnityEngine.Object unityObject)            {                UnityEngine.Debug.LogError(message, unityObject);            }                        UnityEngine.Debug.LogError(message);        }                private static void _logException(Exception e)        {            UnityEngine.Debug.LogException(e);        }        private static DebugTrackStorage _getOrCreateTrackStorage<TOwner>(TOwner owner)        {            Type ownerType = typeof(TOwner);                        if (TRACK_STORAGE.TryGetValue(ownerType, out DebugTrackStorage storage))            {                return storage;            }            return TRACK_STORAGE.InsertAndReturn(ownerType, new DebugTrackStorage(ownerType));        }    }}